// JPA entity - pure persistence concern
@Entity
public class User {
    @Id
    private Long id;
    private String username;
    private String passwordHash;
    private boolean enabled;
    @ElementCollection(fetch = FetchType.EAGER)
    private Set<String> roles;
}

// UserDetails adapter - bridges User to Spring Security
public class CustomUserDetails implements UserDetails {
    private final User user;

    public CustomUserDetails(User user) {
        this.user = user;
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
            .toList();
    }

    @Override
    public String getPassword() {
        return user.getPasswordHash();
    }

    @Override
    public String getUsername() {
        return user.getUsername();
    }

    @Override
    public boolean isEnabled() {
        return user.isEnabled();
    }

    @Override
    public boolean isAccountNonExpired() {
        return true; // implement if you track expiration
    }

    @Override
    public boolean isAccountNonLocked() {
        return true; // implement if you track locking
    }

    @Override
    public boolean isCredentialsNonExpired() {
        return true; // implement if passwords expire
    }
}

@Service
public class CustomUserDetailsService implements UserDetailsService {
    @Autowired
    private UserRepository userRepository;

    @Override
    public UserDetails loadUserByUsername(String username) {
        var user = userRepository.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));

        // Convert role strings to GrantedAuthority objects
        var authorities = user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
            .toList();

        return new org.springframework.security.core.userdetails.User(
            user.getUsername(),
            user.getPasswordHash(),
            authorities // List<GrantedAuthority> passed here
        );
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/admin/**").hasRole("ADMIN") // checks ROLE_ADMIN
                .requestMatchers("/api/user/**").hasAuthority("ROLE_USER") // explicit string
                .requestMatchers("/api/public/**").permitAll()
            )
            .build();
    }
}

@RestController
@RequestMapping("/api/orders")
class OrderController {
    private final OrderService orders;

    OrderController(OrderService orders) {
        this.orders = orders;
    }

    @PostMapping
    ResponseEntity<Order> create(
            @RequestBody OrderRequest request, Authentication authentication) {
        // MVC supplies the current Authentication explicitly.
        return ResponseEntity.ok(orders.create(request, authentication.getName()));
    }
}

@Service
class AuditService {
    String currentUsername() {
        Authentication authentication = SecurityContextHolder.getContext()
            .getAuthentication();
        if (authentication == null || !authentication.isAuthenticated()
                || authentication instanceof AnonymousAuthenticationToken) {
            throw new AccessDeniedException("Authentication is required");
        }
        // getName() works without assuming that the principal is UserDetails.
        return authentication.getName();
    }
}

@Configuration
class SecurityConfig {

    @Bean
    SecurityFilterChain apiSecurity(HttpSecurity http) throws Exception {
        http
            .securityMatcher("/api/**")
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .csrf(csrf -> csrf.disable()) // This chain accepts an explicit bearer header.
            .oauth2ResourceServer(oauth2 ->
                oauth2.jwt(Customizer.withDefaults()));
        return http.build();
    }
}

