// WRONG: plain-text password saved straight to the database
public void register(String username, String rawPassword) {
    User user = new User(username, rawPassword, "ROLE_USER");
    userRepository.save(user); // a single breach exposes every password
}
```
If the database leaks, every account is instantly compromised.

```java
// RIGHT: hash with BCrypt before storing
public void register(String username, String rawPassword) {
    String hash = passwordEncoder.encode(rawPassword); // salted BCrypt hash
    User user = new User(username, hash, "ROLE_USER");
    userRepository.save(user); // only the irreversible hash is stored
}
```
At login you verify with passwordEncoder.matches(raw, storedHash) — you never decrypt.

@Service
public class UserService {
    private final UserRepository users;
    private final PasswordEncoder passwords;

    public UserService(UserRepository users, PasswordEncoder passwords) {
        this.users = users;
        this.passwords = passwords;
    }

    public void register(String username, String rawPassword) {
        String storedValue = passwords.encode(rawPassword);
        users.save(new User(username, storedValue, "ROLE_USER"));
    }

    public boolean passwordMatches(User user, String submittedPassword) {
        return passwords.matches(submittedPassword, user.getPassword());
    }
}

@Configuration
class PasswordConfig {
    @Bean
    PasswordEncoder passwordEncoder() {
        // Benchmark and tune the cost for the deployment instead of copying one number.
        return PasswordEncoderFactories.createDelegatingPasswordEncoder();
    }
}
